import sys
from math import gcd
from functools import reduce

def lcm(a, b):
    return a * b // gcd(a, b)

def lcm_multiple(numbers):
    return reduce(lcm, numbers, 1)

def main():
    import sys
    input = sys.stdin.read().splitlines()
    m, n = map(int, input[0].split())
    dora_days = []
    for line in input[1:]:
        s_i, *stores = map(int, line.split())
        dora_days.append(stores)

    max_prime = 10**5
    prime_count = 0
    primes = []
    sieve = [True] * (max_prime + 1)
    for num in range(2, max_prime + 1):
        if sieve[num]:
            primes.append(num)
            prime_count += 1
            if prime_count >= n:
                break
            for multiple in range(num * num, max_prime + 1, num):
                sieve[multiple] = False

    a = [1] * (n + 1)
    for i, prime in enumerate(primes[:n]):
        a[i + 1] = prime

    for dora_stores in dora_days:
        dora_lcm = lcm_multiple(a[i] for i in dora_stores)
        swiper_stores = [i for i in range(1, n + 1) if i not in dora_stores]
        swiper_lcm = lcm_multiple(a[i] for i in swiper_stores)
        if dora_lcm <= swiper_lcm:
            print("impossible")
            return

    print("possible")

main()
